import pandas as pd


def run(inputs: dict) -> dict:
    stock_balance = inputs["stock_balance"]
    applied_movements = inputs["applied_movements"]
    movements = inputs["movements"]

    # Initialize balances dict keyed by (sku, warehouse) -> on_hand
    balances = {}
    for row in stock_balance.itertuples(index=False):
        balances[(row.sku, row.warehouse)] = int(row.on_hand)

    # Initialize applied set
    applied = set(applied_movements["movement_id"].astype(str).tolist())

    # Sort movements by movement_ts, line_no
    mv = movements.sort_values(by=["movement_ts", "line_no"], kind="mergesort").reset_index(drop=True)

    rejects = []
    newly_applied = []

    for row in mv.itertuples(index=False):
        movement_id = row.movement_id
        if movement_id in applied:
            # skip silently
            continue

        key = (row.sku, row.warehouse)
        current = balances.get(key, 0)
        qty = int(row.qty)
        new_on_hand = current + qty

        if new_on_hand < 0:
            rejects.append({"line_no": row.line_no, "reason": "INSUFFICIENT_STOCK"})
        else:
            balances[key] = new_on_hand
            applied.add(movement_id)
            newly_applied.append(movement_id)

    # Build new_balance output
    if balances:
        nb_rows = [
            {"sku": k[0], "warehouse": k[1], "on_hand": v}
            for k, v in balances.items()
        ]
        new_balance = pd.DataFrame(nb_rows, columns=["sku", "warehouse", "on_hand"])
    else:
        new_balance = pd.DataFrame(columns=["sku", "warehouse", "on_hand"])

    # Build applied_out output
    orig_applied = applied_movements["movement_id"].astype(str).tolist()
    all_applied = orig_applied + newly_applied
    seen = set()
    dedup_applied = []
    for mid in all_applied:
        if mid not in seen:
            seen.add(mid)
            dedup_applied.append(mid)
    applied_out = pd.DataFrame({"movement_id": dedup_applied})

    # Build movement_rejects output
    if rejects:
        movement_rejects = pd.DataFrame(rejects, columns=["line_no", "reason"])
    else:
        movement_rejects = pd.DataFrame(columns=["line_no", "reason"])

    return {
        "new_balance": new_balance,
        "applied_out": applied_out,
        "movement_rejects": movement_rejects,
    }
